func TwoSum(nums []int, target int) []int {
	seen := make(map[int]int)         // map each value we've visited to its index
	for i, n := range nums {          // iterate over the slice once, tracking index and value
		if j, ok := seen[target-n]; ok { // check whether the complement was seen earlier
			return []int{j, i}            // found the pair; return earlier index then current index
		}
		seen[n] = i                   // record current value -> index for future complements
	}
	return nil                        // no pair found (per constraints this should not happen)
}

