func ReverseString(s string) string {
	r := []rune(s)                              // decode the string into runes so multi-byte chars stay intact
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 { // two pointers converging from both ends
		r[i], r[j] = r[j], r[i]                 // swap the outer pair of runes
	}
	return string(r)                            // re-encode the reversed runes back into a string
}

