solutionCode:
package main

import "unicode"

func IsPalindrome(s string) bool {
	r := []rune(s)                                  // work in runes to compare characters safely
	i, j := 0, len(r)-1                             // two pointers at the outer ends
	for i < j {                                     // converge until the pointers meet or cross
		for i < j && !isAlnum(r[i]) {               // skip non-alphanumeric runes on the left
			i++                                     // advance past punctuation/space
		}
		for i < j && !isAlnum(r[j]) {               // skip non-alphanumeric runes on the right
			j--                                     // retreat past punctuation/space
		}
		if unicode.ToLower(r[i]) != unicode.ToLower(r[j]) { // compare the two relevant runes case-insensitively
			return false                            // mismatch means not a palindrome
		}
		i++                                         // move inward from the left
		j--                                         // move inward from the right
	}
	return true                                     // every opposing pair matched
}

func isAlnum(c rune) bool {
	return unicode.IsLetter(c) || unicode.IsDigit(c) // helper: true for letters and digits only
}

