func MaxOf(nums []int) (int, bool) {
	if len(nums) == 0 {        // guard the empty case so we never read nums[0] out of range
		return 0, false        // no maximum exists; signal absence via the bool
	}
	max := nums[0]             // seed the running maximum with the first element
	for _, n := range nums[1:] { // scan the remaining elements
		if n > max {           // found a value larger than the current maximum
			max = n            // update the running maximum
		}
	}
	return max, true           // return the maximum and signal it is valid
}

