func Factorial(n int) int {
	result := 1                  // product accumulator; also the correct answer for n == 0
	for i := 2; i <= n; i++ {    // multiply by 2..n (multiplying by 1 is a no-op, so start at 2)
		result *= i              // fold the next factor into the running product
	}
	return result                // n! (1 when n is 0 or 1)
}

