package main

func Fib(n int) int {
	if n < 2 {                       // base cases: F(0)=0 and F(1)=1 are returned directly
		return n
	}
	prev, curr := 0, 1               // rolling window holding F(i-2) and F(i-1)
	for i := 2; i <= n; i++ {        // build up from F(2) to F(n)
		prev, curr = curr, prev+curr // slide the window: new curr is the sum of the previous two
	}
	return curr                      // curr now holds F(n)
}

