package main

func IsPrime(n int) bool {
	if n < 2 {                       // 0, 1, and negatives are not prime
		return false
	}
	if n%2 == 0 {                    // 2 is the only even prime
		return n == 2
	}
	for i := 3; i*i <= n; i += 2 {   // test only odd divisors up to sqrt(n) (i*i <= n avoids sqrt)
		if n%i == 0 {                // a divisor found means n is composite
			return false
		}
	}
	return true                      // no divisor found, so n is prime
}

