func MergeSorted(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b)) // preallocate the exact final capacity
	i, j := 0, 0                         // read pointers into a and b
	for i < len(a) && j < len(b) {       // while both slices still have elements
		if a[i] <= b[j] {                // take the smaller head (<= keeps the merge stable)
			out = append(out, a[i])
			i++                          // advance the a pointer
		} else {
			out = append(out, b[j])
			j++                          // advance the b pointer
		}
	}
	out = append(out, a[i:]...)          // drain any remaining tail of a (already sorted)
	out = append(out, b[j:]...)          // drain any remaining tail of b (already sorted)
	return out                           // fully merged ascending slice
}

