package main

func RomanToInt(s string) int {
	values := map[byte]int{ // value of each Roman symbol (ASCII bytes are fine here)
		'I': 1, 'V': 5, 'X': 10, 'L': 50,
		'C': 100, 'D': 500, 'M': 1000,
	}
	total := 0                        // running numeric total
	for i := 0; i < len(s); i++ {     // walk left to right over each symbol
		v := values[s[i]]             // numeric value of the current symbol
		if i+1 < len(s) && v < values[s[i+1]] { // current symbol is smaller than the next one
			total -= v                // subtractive case (IV, IX, XL, ...)
		} else {
			total += v                // normal additive case
		}
	}
	return total                      // the decoded integer value
}

