func RemoveDuplicates(nums []int) int {
	if len(nums) == 0 {           // empty slice has zero unique elements
		return 0
	}
	write := 1                    // index 0 is always kept; next unique goes at index 1
	for read := 1; read < len(nums); read++ { // scan from the second element onward
		if nums[read] != nums[read-1] {       // a new value differs from the previous one
			nums[write] = nums[read]          // place it at the write pointer
			write++                           // advance the write pointer
		}
	}
	return write                  // number of unique elements stored in nums[:write]
}

