solutionCode:
package main

func BinarySearch(nums []int, target int) int {
	lo, hi := 0, len(nums)-1            // inclusive search bounds [lo, hi]
	for lo <= hi {                      // continue while the interval is non-empty
		mid := lo + (hi-lo)/2           // midpoint computed to avoid lo+hi overflow
		switch {
		case nums[mid] == target:       // found the target
			return mid
		case nums[mid] < target:        // target is in the right half
			lo = mid + 1
		default:                        // target is in the left half
			hi = mid - 1
		}
	}
	return -1                           // interval emptied without finding the target
}

