package main

func IsAnagram(s, t string) bool {
	if len(s) != len(t) {        // different byte lengths can't be anagrams (true for ASCII inputs)
		return false
	}
	counts := make(map[rune]int) // net frequency of each rune
	for _, r := range s {        // count up every rune in s
		counts[r]++
	}
	for _, r := range t {        // count down every rune in t
		counts[r]--
		if counts[r] < 0 {       // t has a rune more often than s => not an anagram
			return false
		}
	}
	return true                  // equal lengths and no negative counts => perfect match
}

