import (
	"strings" // strings.Fields/Join for splitting and rejoining words
	"unicode" // unicode.ToUpper/ToLower for rune-safe casing
)

// TitleCase upper-cases the first letter of each word, lower-cases the rest.
func TitleCase(s string) string {
	words := strings.Fields(s)                  // split on runs of whitespace, dropping empties
	for i, w := range words {                   // process each word independently
		r := []rune(w)                      // convert to runes so multi-byte chars stay intact
		r[0] = unicode.ToUpper(r[0])        // upper-case the leading rune of the word
		for j := 1; j < len(r); j++ {       // walk the remaining runes
			r[j] = unicode.ToLower(r[j]) // force the tail to lower-case
		}
		words[i] = string(r)                // store the rebuilt word back
	}
	return strings.Join(words, " ")             // re-join words with single spaces
}

