// LengthOfLongestSubstring returns the length of the longest distinct-character window.
func LengthOfLongestSubstring(s string) int {
	last := make(map[byte]int)    // byte -> most recent index where it appeared
	best := 0                     // longest valid window length seen
	start := 0                    // left edge of the current window
	for i := 0; i < len(s); i++ { // right edge scans across the string
		c := s[i]                                   // current character
		if idx, ok := last[c]; ok && idx >= start { // if c repeats inside the window
			start = idx + 1                     // shrink the window to just past the duplicate
		}
		last[c] = i                                 // record/refresh c's latest position
		if w := i - start + 1; w > best {           // current window width
			best = w                            // update the best length
		}
	}
	return best // longest distinct-character substring length
}

