// TwoSum returns 1-based indices of the pair summing to target in a sorted slice.
func TwoSum(numbers []int, target int) []int {
	lo, hi := 0, len(numbers)-1 // pointers at the smallest and largest values
	for lo < hi {               // converge until they meet
		sum := numbers[lo] + numbers[hi] // current candidate sum
		switch {
		case sum == target: // exact match found
			return []int{lo + 1, hi + 1} // convert to 1-based indices
		case sum < target: // sum too small
			lo++ // raise the lower value
		default: // sum too large
			hi-- // lower the upper value
		}
	}
	return nil // unreachable per problem guarantee of exactly one solution
}

