solutionCode:
package main

import "sort" // sort to enable two-pointer scanning and duplicate skipping

// ThreeSum returns all unique zero-sum triplets.
func ThreeSum(nums []int) [][]int {
	sort.Ints(nums)                    // sort so we can two-pointer and skip duplicates
	var res [][]int                    // accumulated unique triplets
	for i := 0; i < len(nums)-2; i++ { // fix the first element of the triplet
		if i > 0 && nums[i] == nums[i-1] { // skip a repeated first element
			continue
		}
		lo, hi := i+1, len(nums)-1 // two pointers over the remaining suffix
		for lo < hi {              // converge toward each other
			sum := nums[i] + nums[lo] + nums[hi] // current triplet sum
			switch {
			case sum < 0: // too small -> need a larger value
				lo++
			case sum > 0: // too large -> need a smaller value
				hi--
			default: // sum == 0 -> record the triplet
				res = append(res, []int{nums[i], nums[lo], nums[hi]})
				lo++ // advance past this pair
				hi--
				for lo < hi && nums[lo] == nums[lo-1] { // skip duplicate second elements
					lo++
				}
				for lo < hi && nums[hi] == nums[hi+1] { // skip duplicate third elements
					hi--
				}
			}
		}
	}
	return res // all unique triplets summing to zero
}

