solutionCode:
package main

import "sort" // sort.Slice to order intervals by start

// MergeIntervals returns the union of overlapping intervals.
func MergeIntervals(intervals [][]int) [][]int {
	if len(intervals) == 0 { // nothing to merge
		return [][]int{}
	}
	sort.Slice(intervals, func(i, j int) bool { // sort ascending by start
		return intervals[i][0] < intervals[j][0]
	})
	res := [][]int{intervals[0]}        // seed with the first interval
	for _, cur := range intervals[1:] { // sweep the remaining intervals
		last := res[len(res)-1]     // the most recently merged interval
		if cur[0] <= last[1] {      // current overlaps the last (start within last's end)
			if cur[1] > last[1] { // extend the end if current reaches further
				last[1] = cur[1] // grow the merged interval in place
			}
		} else { // disjoint -> start a new interval
			res = append(res, cur)
		}
	}
	return res // merged, non-overlapping intervals
}

