// InsertInterval merges newInterval into a sorted, non-overlapping list.
func InsertInterval(intervals [][]int, newInterval []int) [][]int {
	res := [][]int{}                                 // output accumulator
	i, n := 0, len(intervals)                        // scan index and length
	for i < n && intervals[i][1] < newInterval[0] {  // intervals entirely left of newInterval
		res = append(res, intervals[i])          // emit them unchanged
		i++
	}
	for i < n && intervals[i][0] <= newInterval[1] { // intervals overlapping newInterval
		if intervals[i][0] < newInterval[0] {    // widen the left edge if needed
			newInterval[0] = intervals[i][0]
		}
		if intervals[i][1] > newInterval[1] {    // widen the right edge if needed
			newInterval[1] = intervals[i][1]
		}
		i++ // consume the overlapping interval into newInterval
	}
	res = append(res, newInterval) // emit the fully merged interval
	for i < n {                    // intervals entirely right of newInterval
		res = append(res, intervals[i]) // emit the remainder unchanged
		i++
	}
	return res // sorted, non-overlapping result
}

