solutionCode:
package main

import "container/heap" // heap interface for the priority queue

// item pairs a value with its frequency for the heap.
type item struct {
	val, freq int // the value and how often it appears
}

// minHeap orders items by ascending frequency (smallest freq at the top).
type minHeap []item

func (h minHeap) Len() int           { return len(h) }                 // number of items
func (h minHeap) Less(i, j int) bool { return h[i].freq < h[j].freq } // min by frequency
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }       // standard swap
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }      // append on push
func (h *minHeap) Pop() any {                                           // remove the last element
	old := *h      // current backing slice
	n := len(old)  // length before pop
	it := old[n-1] // element heap moved to the end
	*h = old[:n-1] // shrink the slice
	return it      // return the popped item
}

// TopKFrequent uses a size-k min-heap to keep the most frequent values.
func TopKFrequent(nums []int, k int) []int {
	freq := make(map[int]int) // value -> frequency
	for _, n := range nums {  // tally each number
		freq[n]++
	}
	h := &minHeap{}          // empty min-heap
	heap.Init(h)             // establish heap invariants
	for v, f := range freq { // consider each distinct value
		heap.Push(h, item{v, f}) // add it to the heap
		if h.Len() > k {         // keep only the top k by evicting the smallest freq
			heap.Pop(h)
		}
	}
	res := make([]int, h.Len()) // collect the survivors
	for i := range res {        // drain the heap
		res[i] = heap.Pop(h).(item).val // extract each value
	}
	return res // the k most frequent values
}

