package main

// IsValid checks balanced bracket nesting using a stack.
func IsValid(s string) bool {
	pairs := map[byte]byte{')': '(', ']': '[', '}': '{'} // close -> matching open
	stack := make([]byte, 0, len(s))                     // stack of pending opens
	for i := 0; i < len(s); i++ {                        // scan each character
		c := s[i]                               // current bracket
		if open, isClose := pairs[c]; isClose { // a closing bracket
			if len(stack) == 0 || stack[len(stack)-1] != open { // top must be its matching open
				return false // mismatch or empty stack -> invalid
			}
			stack = stack[:len(stack)-1] // pop the matched open
		} else { // an opening bracket
			stack = append(stack, c) // push it for later matching
		}
	}
	return len(stack) == 0 // valid only if every open was closed
}

