package main

// MinStack keeps a parallel stack of running minimums for O(1) GetMin.
type MinStack struct {
	data []int // the actual stack values
	mins []int // mins[i] holds the minimum of data[0..i]
}

// Constructor returns an empty MinStack.
func Constructor() MinStack {
	return MinStack{} // nil slices are valid empty stacks
}

// Push adds x and updates the running minimum.
func (s *MinStack) Push(x int) {
	s.data = append(s.data, x)                         // push the value
	if len(s.mins) == 0 || x < s.mins[len(s.mins)-1] { // new minimum so far?
		s.mins = append(s.mins, x) // record x as the current minimum
	} else {
		s.mins = append(s.mins, s.mins[len(s.mins)-1]) // carry forward the prior minimum
	}
}

// Pop removes the top element.
func (s *MinStack) Pop() {
	s.data = s.data[:len(s.data)-1] // drop the top value
	s.mins = s.mins[:len(s.mins)-1] // drop its paired minimum
}

// Top returns the top element.
func (s *MinStack) Top() int {
	return s.data[len(s.data)-1] // last pushed value
}

// GetMin returns the current minimum in O(1).
func (s *MinStack) GetMin() int {
	return s.mins[len(s.mins)-1] // minimum tracked at the top of mins
}

