// ListNode is a singly linked list node.
type ListNode struct {
	Val  int       // node payload
	Next *ListNode // pointer to the next node (nil at the tail)
}

// ReverseList reverses the list iteratively in place.
func ReverseList(head *ListNode) *ListNode {
	var prev *ListNode // reversed portion's head (starts as nil = new tail)
	cur := head        // node currently being rewired
	for cur != nil {   // walk to the end of the list
		next := cur.Next // remember the next node before we overwrite the pointer
		cur.Next = prev  // reverse this node's link to point backward
		prev = cur       // advance prev into the reversed section
		cur = next       // advance cur to the saved next node
	}
	return prev // prev is the new head once cur runs off the end
}

