// ListNode is a singly linked list node.
type ListNode struct {
	Val  int       // payload
	Next *ListNode // next pointer (may form a cycle)
}

// HasCycle detects a cycle using Floyd's two-pointer algorithm.
func HasCycle(head *ListNode) bool {
	slow, fast := head, head              // both pointers start at the head
	for fast != nil && fast.Next != nil { // fast needs two nodes ahead to advance
		slow = slow.Next      // tortoise moves one step
		fast = fast.Next.Next // hare moves two steps
		if slow == fast {     // same node => the hare lapped the tortoise
			return true // a cycle exists
		}
	}
	return false // fast reached nil => the list terminates, no cycle
}

