// ListNode is a singly linked list node.
type ListNode struct {
	Val  int       // payload
	Next *ListNode // next pointer
}

// MergeTwoLists splices two sorted lists into one sorted list.
func MergeTwoLists(l1, l2 *ListNode) *ListNode {
	dummy := &ListNode{}         // sentinel head simplifies edge handling
	tail := dummy                // tail always points at the last node of the merged list
	for l1 != nil && l2 != nil { // while both lists still have nodes
		if l1.Val <= l2.Val { // pick the smaller front node
			tail.Next = l1 // splice l1's node onto the result
			l1 = l1.Next   // advance l1
		} else {
			tail.Next = l2 // splice l2's node onto the result
			l2 = l2.Next   // advance l2
		}
		tail = tail.Next // move the tail forward to the spliced node
	}
	if l1 != nil { // attach whatever remains of l1
		tail.Next = l1
	} else { // otherwise attach the rest of l2
		tail.Next = l2
	}
	return dummy.Next // skip the sentinel to return the real head
}

