package main

import "container/list" // doubly linked list for O(1) move/remove

// entry is the payload stored in each list element.
type entry struct {
	key, value int // key needed to delete from the map on eviction
}

// LRUCache combines a map (O(1) lookup) with a list (O(1) recency ordering).
type LRUCache struct {
	cap   int                   // maximum number of entries
	ll    *list.List            // front = most recently used, back = least
	items map[int]*list.Element // key -> list element holding its entry
}

// Constructor builds an empty cache with the given capacity.
func Constructor(capacity int) LRUCache {
	return LRUCache{
		cap:   capacity,                   // store the capacity
		ll:    list.New(),                 // fresh empty list
		items: make(map[int]*list.Element), // empty index
	}
}

// Get returns the value for key, or -1, and marks it most recently used.
func (c *LRUCache) Get(key int) int {
	if el, ok := c.items[key]; ok { // cache hit
		c.ll.MoveToFront(el)           // mark as most recently used
		return el.Value.(*entry).value // return the stored value
	}
	return -1 // miss
}

// Put inserts or updates key, evicting the LRU entry if over capacity.
func (c *LRUCache) Put(key, value int) {
	if el, ok := c.items[key]; ok { // key already present -> update
		el.Value.(*entry).value = value // overwrite the value
		c.ll.MoveToFront(el)            // refresh recency
		return
	}
	el := c.ll.PushFront(&entry{key, value}) // insert as most recently used
	c.items[key] = el                        // index it
	if c.ll.Len() > c.cap {                  // over capacity -> evict
		oldest := c.ll.Back()                      // least recently used element
		c.ll.Remove(oldest)                        // unlink it from the list
		delete(c.items, oldest.Value.(*entry).key) // drop it from the map
	}
}

