package main

func maxSlidingWindow(nums []int, k int) []int {
	if len(nums) == 0 || k <= 0 { // guard against empty input or invalid window
		return []int{} // nothing to compute
	}
	res := make([]int, 0, len(nums)-k+1) // pre-size output to number of windows
	deque := make([]int, 0, len(nums))   // holds indices, values decreasing front->back
	for i, v := range nums {             // slide the window one index at a time
		for len(deque) > 0 && nums[deque[len(deque)-1]] < v { // pop smaller tail values
			deque = deque[:len(deque)-1] // they can never be a future maximum
		}
		deque = append(deque, i) // current index is a maximum candidate
		if deque[0] <= i-k {     // front index has slid out of the window
			deque = deque[1:] // drop it
		}
		if i >= k-1 { // first full window has formed
			res = append(res, nums[deque[0]]) // front always holds the window max
		}
	}
	return res // one maximum per window
}

