solutionCode:
package main

func numIslands(grid [][]byte) int {
	if len(grid) == 0 { // empty grid has no islands
		return 0
	}
	rows, cols := len(grid), len(grid[0]) // grid dimensions
	count := 0                            // islands discovered so far
	var dfs func(r, c int)                // recursive flood fill
	dfs = func(r, c int) {                // sink all land reachable from (r,c)
		if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '1' { // out of bounds or water
			return // stop the recursion branch
		}
		grid[r][c] = '0' // mark as visited by sinking it
		dfs(r+1, c)      // explore down
		dfs(r-1, c)      // explore up
		dfs(r, c+1)      // explore right
		dfs(r, c-1)      // explore left
	}
	for r := 0; r < rows; r++ { // scan every cell
		for c := 0; c < cols; c++ {
			if grid[r][c] == '1' { // unvisited land starts a new island
				count++   // one more island
				dfs(r, c) // sink the whole island
			}
		}
	}
	return count // total connected land components
}

