package main

type Node struct {
	Val       int
	Neighbors []*Node
}

func cloneGraph(node *Node) *Node {
	if node == nil { // empty graph clones to nil
		return nil
	}
	clones := map[*Node]*Node{}                  // original node -> its clone
	clones[node] = &Node{Val: node.Val}          // create the clone of the entry node
	queue := []*Node{node}                       // BFS frontier of originals
	for len(queue) > 0 {                         // process until all nodes seen
		cur := queue[0]                      // current original node
		queue = queue[1:]                    // pop the front
		for _, nb := range cur.Neighbors {   // visit each neighbor edge
			if _, ok := clones[nb]; !ok { // first time seeing this neighbor
				clones[nb] = &Node{Val: nb.Val} // create its clone
				queue = append(queue, nb)       // schedule it for exploration
			}
			clones[cur].Neighbors = append(clones[cur].Neighbors, clones[nb]) // link clone edge
		}
	}
	return clones[node] // clone of the original entry point
}

