solutionCode:
package main

func coinChange(coins []int, amount int) int {
	const inf = 1 << 30          // sentinel meaning 'unreachable'
	dp := make([]int, amount+1)  // dp[x] = fewest coins to make x
	for i := 1; i <= amount; i++ { // dp[0] stays 0 (zero coins for zero)
		dp[i] = inf // start every positive amount as unreachable
	}
	for x := 1; x <= amount; x++ {       // build up each target amount
		for _, c := range coins {    // try every denomination
			if c <= x && dp[x-c]+1 < dp[x] { // coin fits and improves the count
				dp[x] = dp[x-c] + 1 // take one coin c plus best for the remainder
			}
		}
	}
	if dp[amount] == inf { // never reached the target
		return -1
	}
	return dp[amount] // minimum coins for the full amount
}

