package main

func climbStairs(n int) int {
	if n <= 2 { // 1 way for n=1, 2 ways for n=2 (and 1 way for n=0)
		if n <= 0 {
			return 1 // one way to stand still at the bottom
		}
		return n // n==1 -> 1, n==2 -> 2
	}
	prev, cur := 1, 2 // ways to reach step 1 and step 2
	for i := 3; i <= n; i++ { // roll forward to step n
		prev, cur = cur, prev+cur // next = sum of the previous two
	}
	return cur // ways to reach step n
}

