package main

func rob(nums []int) int {
	prev, cur := 0, 0 // best loot up to house i-2 and i-1
	for _, money := range nums { // consider each house in order
		take := prev + money // rob this house plus the best from two houses back
		next := cur          // assume we skip this house (keep previous best)
		if take > next {     // robbing here is better
			next = take
		}
		prev, cur = cur, next // shift the window forward
	}
	return cur // best loot including the last house decision
}

