package main

func longestCommonSubsequence(a, b string) int {
	n, m := len(a), len(b)               // lengths of the two strings
	dp := make([][]int, n+1)             // dp[i][j] = LCS of a[:i] and b[:j]
	for i := range dp {                  // allocate each row (zero-initialized)
		dp[i] = make([]int, m+1)
	}
	for i := 1; i <= n; i++ {            // consider each prefix of a
		for j := 1; j <= m; j++ {    // against each prefix of b
			if a[i-1] == b[j-1] { // matching characters extend the LCS
				dp[i][j] = dp[i-1][j-1] + 1
			} else if dp[i-1][j] >= dp[i][j-1] { // otherwise drop one char
				dp[i][j] = dp[i-1][j] // best by dropping a's char
			} else {
				dp[i][j] = dp[i][j-1] // best by dropping b's char
			}
		}
	}
	return dp[n][m] // LCS of the full strings
}

