package main

import "sort"

func topKFrequent(words []string, k int) []string {
	freq := map[string]int{}        // word -> occurrence count
	for _, w := range words {       // tally every word
		freq[w]++
	}
	uniq := make([]string, 0, len(freq)) // distinct words to rank
	for w := range freq {                // collect map keys
		uniq = append(uniq, w)
	}
	sort.Slice(uniq, func(i, j int) bool { // order by frequency desc, then word asc
		if freq[uniq[i]] != freq[uniq[j]] { // different counts -> higher count first
			return freq[uniq[i]] > freq[uniq[j]]
		}
		return uniq[i] < uniq[j] // tie -> lexicographically smaller first
	})
	if k > len(uniq) { // never return more than we have
		k = len(uniq)
	}
	return uniq[:k] // top k after sorting
}

