package main

func setZeroes(matrix [][]int) {
	if len(matrix) == 0 { // nothing to do for an empty matrix
		return
	}
	rows, cols := len(matrix), len(matrix[0]) // dimensions
	firstRowZero, firstColZero := false, false // whether the marker line itself must be zeroed
	for c := 0; c < cols; c++ { // check the first row for any zero
		if matrix[0][c] == 0 {
			firstRowZero = true
		}
	}
	for r := 0; r < rows; r++ { // check the first column for any zero
		if matrix[r][0] == 0 {
			firstColZero = true
		}
	}
	for r := 1; r < rows; r++ { // scan the inner matrix
		for c := 1; c < cols; c++ {
			if matrix[r][c] == 0 { // record the zero in the markers
				matrix[r][0] = 0 // mark this row
				matrix[0][c] = 0 // mark this column
			}
		}
	}
	for r := 1; r < rows; r++ { // apply markers to the inner matrix
		for c := 1; c < cols; c++ {
			if matrix[r][0] == 0 || matrix[0][c] == 0 { // row or column flagged
				matrix[r][c] = 0
			}
		}
	}
	if firstRowZero { // finally zero the first row if needed
		for c := 0; c < cols; c++ {
			matrix[0][c] = 0
		}
	}
	if firstColZero { // and the first column if needed
		for r := 0; r < rows; r++ {
			matrix[r][0] = 0
		}
	}
}

