package main

func rotate(matrix [][]int) {
	n := len(matrix)             // square dimension
	for i := 0; i < n; i++ {     // transpose across the main diagonal
		for j := i + 1; j < n; j++ { // only upper triangle to swap once
			matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j] // mirror element
		}
	}
	for i := 0; i < n; i++ { // reverse each row to complete the clockwise turn
		for l, r := 0, n-1; l < r; l, r = l+1, r-1 { // two-pointer reverse
			matrix[i][l], matrix[i][r] = matrix[i][r], matrix[i][l] // swap ends inward
		}
	}
}

