package main

func spiralOrder(matrix [][]int) []int {
	if len(matrix) == 0 { // empty input -> empty output
		return []int{}
	}
	top, bottom := 0, len(matrix)-1      // current row bounds
	left, right := 0, len(matrix[0])-1   // current column bounds
	res := make([]int, 0, len(matrix)*len(matrix[0])) // pre-size to total cells
	for top <= bottom && left <= right { // while a valid band remains
		for c := left; c <= right; c++ { // traverse the top row left->right
			res = append(res, matrix[top][c])
		}
		top++ // top row consumed
		for r := top; r <= bottom; r++ { // traverse the right column top->bottom
			res = append(res, matrix[r][right])
		}
		right-- // right column consumed
		if top <= bottom { // bottom row still exists
			for c := right; c >= left; c-- { // traverse bottom row right->left
				res = append(res, matrix[bottom][c])
			}
			bottom-- // bottom row consumed
		}
		if left <= right { // left column still exists
			for r := bottom; r >= top; r-- { // traverse left column bottom->top
				res = append(res, matrix[r][left])
			}
			left++ // left column consumed
		}
	}
	return res // elements in spiral order
}

