package main

func search(nums []int, target int) int {
	lo, hi := 0, len(nums)-1 // inclusive search bounds
	for lo <= hi {           // standard binary-search loop
		mid := lo + (hi-lo)/2 // midpoint without overflow
		if nums[mid] == target { // found it
			return mid
		}
		if nums[lo] <= nums[mid] { // left half [lo..mid] is sorted
			if nums[lo] <= target && target < nums[mid] { // target lies in the sorted left half
				hi = mid - 1 // search left
			} else {
				lo = mid + 1 // search right
			}
		} else { // right half [mid..hi] is sorted
			if nums[mid] < target && target <= nums[hi] { // target lies in the sorted right half
				lo = mid + 1 // search right
			} else {
				hi = mid - 1 // search left
			}
		}
	}
	return -1 // target not present
}

