func findMin(nums []int) int {
	lo, hi := 0, len(nums)-1 // search bounds
	for lo < hi {            // converge to a single element
		mid := lo + (hi-lo)/2 // midpoint without overflow
		if nums[mid] > nums[hi] { // min lies to the right of mid
			lo = mid + 1 // discard the left half including mid
		} else { // nums[mid] <= nums[hi]: min is at mid or to its left
			hi = mid // keep mid as a candidate
		}
	}
	return nums[lo] // lo == hi points at the minimum
}

