solutionCode:
package main

import "sync" // WaitGroup to coordinate goroutines

// ParallelMap applies fn to each element concurrently, preserving order.
func ParallelMap[T any, R any](in []T, fn func(T) R) []R {
	out := make([]R, len(in))   // pre-size the result so each goroutine writes its own index (no shared mutation race)
	var wg sync.WaitGroup       // tracks the outstanding goroutines
	wg.Add(len(in))             // register one unit of work per input element
	for i, v := range in {      // iterate over inputs with index i and value v
		go func(idx int, val T) { // capture idx and val by value to avoid the loop-variable capture bug
			defer wg.Done()       // signal completion when this goroutine returns
			out[idx] = fn(val)    // write result into its dedicated slot, keeping order
		}(i, v)               // pass i and v explicitly so each goroutine sees its own copy
	}
	wg.Wait()                   // block until every goroutine has finished
	return out                  // results are in the same order as the input
}

