package main

// Map transforms each element of s using f, returning a new slice.
func Map[T any, R any](s []T, f func(T) R) []R {
	out := make([]R, len(s)) // exact capacity: one output per input
	for i, v := range s {    // walk every element with its index
		out[i] = f(v)        // store the transformed value at the same position
	}
	return out               // mapped slice, same length and order
}

// Filter keeps only the elements of s for which pred returns true.
func Filter[T any](s []T, pred func(T) bool) []T {
	out := make([]T, 0, len(s)) // reserve capacity up to len(s) to avoid regrowth
	for _, v := range s {       // examine each element
		if pred(v) {            // include only those satisfying the predicate
			out = append(out, v) // append survivors in order
		}
	}
	return out                  // filtered subset preserving original order
}

// Reduce folds s into a single value starting from init, combining with f.
func Reduce[T any, R any](s []T, init R, f func(R, T) R) R {
	acc := init           // accumulator seeded with the initial value
	for _, v := range s { // fold left across the slice
		acc = f(acc, v)   // combine the running accumulator with the next element
	}
	return acc            // final folded result
}

