// MinOf returns the smallest argument and true, or the zero value and false if none.
func MinOf[T cmp.Ordered](xs ...T) (T, bool) {
	if len(xs) == 0 { // no arguments: nothing to compare
		var zero T    // typed zero value for T
		return zero, false
	}
	best := xs[0]            // assume the first element is the minimum
	for _, v := range xs[1:] { // scan the remaining elements
		if v < best {        // Ordered guarantees < is defined for T
			best = v         // found a smaller value
		}
	}
	return best, true        // smallest value found
}

// MaxOf returns the largest argument and true, or the zero value and false if none.
func MaxOf[T cmp.Ordered](xs ...T) (T, bool) {
	if len(xs) == 0 { // empty input -> no maximum
		var zero T
		return zero, false
	}
	best := xs[0]            // start with the first element
	for _, v := range xs[1:] { // compare against the rest
		if v > best {        // strictly greater becomes the new best
			best = v
		}
	}
	return best, true        // largest value found
}

