package main

import "container/heap" // provides the heap algorithms over heap.Interface

type ListNode struct {
	Val  int       // node value
	Next *ListNode // pointer to the next node
}

// nodeHeap is a min-heap of *ListNode ordered by Val.
type nodeHeap []*ListNode

func (h nodeHeap) Len() int            { return len(h) }                  // number of items
func (h nodeHeap) Less(i, j int) bool  { return h[i].Val < h[j].Val }    // min-heap: smaller Val has priority
func (h nodeHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }       // swap elements for sift operations
func (h *nodeHeap) Push(x any)         { *h = append(*h, x.(*ListNode)) } // append a node (pointer receiver mutates slice)
func (h *nodeHeap) Pop() any {                                            // remove and return the last element
	old := *h          // current backing slice
	n := len(old)      // length before removal
	item := old[n-1]   // heap places the popped min at the end
	*h = old[:n-1]     // shrink the slice
	return item        // return the extracted node
}

// MergeKLists merges k sorted lists into one sorted list using a min-heap.
func MergeKLists(lists []*ListNode) *ListNode {
	h := &nodeHeap{}            // empty min-heap
	for _, l := range lists {  // seed the heap with each list's head
		if l != nil {          // skip empty lists
			*h = append(*h, l) // collect non-nil heads before heapifying
		}
	}
	heap.Init(h)               // establish heap order in O(k)
	dummy := &ListNode{}       // sentinel head simplifies appending
	tail := dummy              // tail tracks the last node of the merged list
	for h.Len() > 0 {          // until every node has been consumed
		node := heap.Pop(h).(*ListNode) // pop the smallest available node
		tail.Next = node               // attach it to the output list
		tail = node                    // advance the tail
		if node.Next != nil {          // if the popped list still has nodes
			heap.Push(h, node.Next)    // push the next node from that list
		}
	}
	return dummy.Next          // skip the sentinel to return the real head
}

