package main

// Trap returns the total trapped water using two converging pointers.
func Trap(height []int) int {
	left, right := 0, len(height)-1 // pointers at both ends
	leftMax, rightMax := 0, 0       // tallest bar seen so far from each side
	total := 0                      // accumulated trapped water
	for left < right {              // converge until the pointers meet
		if height[left] < height[right] { // the smaller side bounds the water level
			if height[left] >= leftMax {  // current bar is a new left wall
				leftMax = height[left]    // raise the left boundary
			} else {                      // bar is below the left wall
				total += leftMax - height[left] // water sits on top of this bar
			}
			left++                        // move the left pointer inward
		} else {                          // right side is the limiting wall
			if height[right] >= rightMax { // current bar is a new right wall
				rightMax = height[right]   // raise the right boundary
			} else {                       // bar is below the right wall
				total += rightMax - height[right] // trapped water above this bar
			}
			right--                        // move the right pointer inward
		}
	}
	return total // total volume of trapped water
}

