package main

import "math" // for +/- infinity sentinels at partition edges

// FindMedianSortedArrays returns the median via binary search partitioning.
func FindMedianSortedArrays(a, b []int) float64 {
	if len(a) > len(b) {        // always binary-search the smaller array for O(log min(m,n))
		a, b = b, a             // swap so a is the shorter slice
	}
	m, n := len(a), len(b)      // sizes of the two arrays
	lo, hi := 0, m              // search the cut position in a within [0, m]
	half := (m + n + 1) / 2     // number of elements in the combined left half
	for lo <= hi {              // binary search over the partition of a
		i := (lo + hi) / 2      // elements taken from a on the left side
		j := half - i           // elements taken from b on the left side
		aLeft := math.Inf(-1)   // value just left of a's cut (default -inf when i==0)
		if i > 0 {
			aLeft = float64(a[i-1])
		}
		aRight := math.Inf(1)   // value just right of a's cut (default +inf when i==m)
		if i < m {
			aRight = float64(a[i])
		}
		bLeft := math.Inf(-1)   // value just left of b's cut
		if j > 0 {
			bLeft = float64(b[j-1])
		}
		bRight := math.Inf(1)   // value just right of b's cut
		if j < n {
			bRight = float64(b[j])
		}
		if aLeft <= bRight && bLeft <= aRight { // correct partition: left maxes <= right mins
			if (m+n)%2 == 1 {                   // odd total: median is the largest of the left half
				return math.Max(aLeft, bLeft)
			}
			// even total: average of left-half max and right-half min
			return (math.Max(aLeft, bLeft) + math.Min(aRight, bRight)) / 2
		} else if aLeft > bRight { // a's left is too big: move the cut in a left
			hi = i - 1
		} else { // a's left is too small: move the cut in a right
			lo = i + 1
		}
	}
	return 0 // unreachable for valid sorted inputs
}

