package main

// LadderLength returns the shortest transformation length via breadth-first search.
func LadderLength(begin, end string, wordList []string) int {
	dict := make(map[string]bool, len(wordList)) // set of usable words for O(1) membership
	for _, w := range wordList {                 // populate the dictionary set
		dict[w] = true
	}
	if !dict[end] { // end must be reachable in the word list
		return 0
	}
	queue := []string{begin} // BFS frontier starting from the begin word
	steps := 1               // begin counts as the first word in the sequence
	for len(queue) > 0 {     // process the graph level by level
		next := []string{}   // words discovered at the next BFS level
		for _, word := range queue { // expand every word at the current level
			if word == end {         // reached the target word
				return steps
			}
			bytes := []byte(word)        // mutable copy for generating neighbors
			for i := 0; i < len(bytes); i++ { // try changing each position
				orig := bytes[i]              // remember the original letter
				for c := byte('a'); c <= 'z'; c++ { // try every lowercase letter
					if c == orig {               // skip the unchanged word
						continue
					}
					bytes[i] = c                 // form a candidate neighbor
					cand := string(bytes)        // materialize the candidate string
					if dict[cand] {              // valid only if in the dictionary
						next = append(next, cand) // enqueue for the next level
						delete(dict, cand)       // mark visited by removing from the set
					}
				}
				bytes[i] = orig // restore the position before moving on
			}
		}
		queue = next // advance BFS to the next level
		steps++      // every level deepens the sequence by one
	}
	return 0 // target unreachable
}

