package main

import (
	"container/heap" // priority queue support
	"math"           // for the unreachable sentinel
)

// item is a (node, distance) entry in the priority queue.
type item struct {
	node int // graph vertex
	dist int // current best-known distance to node
}

// pq is a min-heap ordered by dist.
type pq []item

func (p pq) Len() int            { return len(p) }                 // queue size
func (p pq) Less(i, j int) bool  { return p[i].dist < p[j].dist } // smallest distance first
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }       // swap for sifting
func (p *pq) Push(x any)         { *p = append(*p, x.(item)) }     // add an entry
func (p *pq) Pop() any {                                           // remove the last (min) entry
	old := *p          // backing slice
	n := len(old)      // current length
	it := old[n-1]     // popped element sits at the end
	*p = old[:n-1]     // shrink the slice
	return it          // return the extracted item
}

// Dijkstra computes shortest distances from src to all n nodes.
func Dijkstra(graph map[int][][2]int, src int, n int) []int {
	dist := make([]int, n)        // distance array, indexed by node
	for i := range dist {         // initialize every distance to infinity
		dist[i] = math.MaxInt
	}
	dist[src] = 0                 // distance to the source is zero
	h := &pq{{node: src, dist: 0}} // start the heap with the source
	heap.Init(h)                  // establish heap order
	for h.Len() > 0 {             // process until the queue drains
		cur := heap.Pop(h).(item) // node with the smallest tentative distance
		if cur.dist > dist[cur.node] { // stale entry: a better path was already finalized
			continue
		}
		for _, edge := range graph[cur.node] { // relax each outgoing edge
			next, w := edge[0], edge[1]        // neighbor and edge weight
			if nd := cur.dist + w; nd < dist[next] { // found a shorter path to next
				dist[next] = nd                  // update the best distance
				heap.Push(h, item{node: next, dist: nd}) // queue the improved entry
			}
		}
	}
	return dist // shortest distances (math.MaxInt means unreachable)
}

