package main

// MinDistance computes the Levenshtein distance with a 2D DP table.
func MinDistance(word1, word2 string) int {
	m, n := len(word1), len(word2)   // lengths of the two words
	dp := make([][]int, m+1)         // dp[i][j] = edits to convert word1[:i] -> word2[:j]
	for i := range dp {              // allocate each row
		dp[i] = make([]int, n+1)
		dp[i][0] = i                 // converting i chars to empty = i deletions
	}
	for j := 0; j <= n; j++ {        // base row: empty word1 to word2[:j]
		dp[0][j] = j                 // = j insertions
	}
	for i := 1; i <= m; i++ {        // fill row by row
		for j := 1; j <= n; j++ {    // and column by column
			if word1[i-1] == word2[j-1] { // characters match: no new edit
				dp[i][j] = dp[i-1][j-1]
			} else { // take the cheapest of delete, insert, or substitute, plus one
				dp[i][j] = 1 + min3(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
			}
		}
	}
	return dp[m][n] // full-prefix answer
}

// min3 returns the smallest of three integers.
func min3(a, b, c int) int {
	m := a       // assume the first is smallest
	if b < m {   // compare against the second
		m = b
	}
	if c < m {   // compare against the third
		m = c
	}
	return m     // smallest of the three
}

