// WordBreak reports whether s can be split into dictionary words.
func WordBreak(s string, wordDict []string) bool {
	words := make(map[string]bool, len(wordDict)) // dictionary set for O(1) lookup
	for _, w := range wordDict {                  // load the dictionary
		words[w] = true
	}
	n := len(s)                 // length of the input string
	dp := make([]bool, n+1)     // dp[i] = true if s[:i] is fully segmentable
	dp[0] = true                // empty prefix is trivially segmentable
	for i := 1; i <= n; i++ {   // consider every prefix length i
		for j := 0; j < i; j++ { // try every split point j producing s[j:i]
			if dp[j] && words[s[j:i]] { // prefix s[:j] works and s[j:i] is a word
				dp[i] = true        // then s[:i] is segmentable
				break               // no need to check other splits for i
			}
		}
	}
	return dp[n] // whether the whole string is segmentable
}

