package main

import (
	"strconv" // int <-> string conversion
	"strings" // join and split the serialized tokens
)

type TreeNode struct {
	Val         int       // node value
	Left, Right *TreeNode // child pointers
}

// Serialize encodes the tree in preorder with '#' marking nil children.
func Serialize(root *TreeNode) string {
	var tokens []string        // collected preorder tokens
	var build func(n *TreeNode) // recursive preorder walker
	build = func(n *TreeNode) {
		if n == nil {               // nil child becomes a sentinel marker
			tokens = append(tokens, "#")
			return
		}
		tokens = append(tokens, strconv.Itoa(n.Val)) // record this node's value
		build(n.Left)               // then the left subtree (preorder)
		build(n.Right)              // then the right subtree
	}
	build(root)                     // walk the whole tree
	return strings.Join(tokens, ",") // comma-separated token stream
}

// Deserialize rebuilds the tree from the preorder token stream.
func Deserialize(data string) *TreeNode {
	tokens := strings.Split(data, ",") // split back into tokens
	idx := 0                           // cursor into the token slice
	var build func() *TreeNode         // recursive consumer in the same preorder
	build = func() *TreeNode {
		tok := tokens[idx] // current token
		idx++              // advance the cursor
		if tok == "#" {    // sentinel means a nil child
			return nil
		}
		val, _ := strconv.Atoi(tok) // parse the node value
		node := &TreeNode{Val: val} // construct the node
		node.Left = build()         // build left subtree first (matches serialize order)
		node.Right = build()        // then the right subtree
		return node                 // fully built subtree rooted here
	}
	return build() // reconstruct from the first token
}

