// LowestCommonAncestor finds the LCA of p and q using BST ordering.
func LowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
	cur := root // walk down from the root
	for cur != nil { // descend until the split point is found
		if p.Val < cur.Val && q.Val < cur.Val { // both targets are smaller
			cur = cur.Left  // LCA must be in the left subtree
		} else if p.Val > cur.Val && q.Val > cur.Val { // both targets are larger
			cur = cur.Right // LCA must be in the right subtree
		} else { // p and q split here (or one equals cur): this is the LCA
			return cur
		}
	}
	return nil // empty tree
}

