import "math" // for the initial infinite bounds

type TreeNode struct {
	Val         int       // node value
	Left, Right *TreeNode // children
}

// IsValidBST validates the tree by tightening (low, high) bounds per node.
func IsValidBST(root *TreeNode) bool {
	var valid func(n *TreeNode, low, high int) bool // recursive bound-checker
	valid = func(n *TreeNode, low, high int) bool {
		if n == nil { // an empty subtree is always valid
			return true
		}
		if n.Val <= low || n.Val >= high { // value must lie strictly inside the open interval
			return false
		}
		// left subtree must be < n.Val; right subtree must be > n.Val
		return valid(n.Left, low, n.Val) && valid(n.Right, n.Val, high)
	}
	return valid(root, math.MinInt, math.MaxInt) // start with unbounded range
}

