// LevelOrder returns values grouped per level using BFS.
func LevelOrder(root *TreeNode) [][]int {
	if root == nil { // empty tree -> empty result
		return [][]int{}
	}
	var result [][]int            // one slice of values per level
	queue := []*TreeNode{root}    // BFS frontier starting at the root
	for len(queue) > 0 {          // process one level per outer iteration
		size := len(queue)        // number of nodes on the current level
		level := make([]int, 0, size) // values collected for this level
		for i := 0; i < size; i++ {   // dequeue exactly the current level's nodes
			node := queue[0]          // front of the queue
			queue = queue[1:]         // pop it
			level = append(level, node.Val) // record its value
			if node.Left != nil {     // enqueue children for the next level
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		result = append(result, level) // commit this level's values
	}
	return result // values grouped by depth
}

