type TreeNode struct {
	Val         int       // node value
	Left, Right *TreeNode // children
}

// KthSmallest returns the k-th smallest value via iterative in-order traversal.
func KthSmallest(root *TreeNode, k int) int {
	stack := []*TreeNode{} // explicit stack for in-order traversal
	cur := root            // pointer used to descend left spines
	for cur != nil || len(stack) > 0 { // continue while there are nodes to visit
		for cur != nil { // push the entire left spine
			stack = append(stack, cur)
			cur = cur.Left
		}
		cur = stack[len(stack)-1]   // pop the smallest unvisited node
		stack = stack[:len(stack)-1] // remove it from the stack
		k--                          // count this in-order visit
		if k == 0 {                  // reached the k-th smallest
			return cur.Val
		}
		cur = cur.Right // then traverse the right subtree in-order
	}
	return -1 // k larger than the number of nodes
}

