package main

// LengthOfLIS returns the LIS length using patience sorting in O(N log N).
func LengthOfLIS(nums []int) int {
	tails := make([]int, 0, len(nums)) // tails[i] = smallest possible tail of an LIS of length i+1
	for _, x := range nums {           // process each number once
		lo, hi := 0, len(tails)        // binary search for the first tail >= x
		for lo < hi {                  // standard lower-bound binary search
			mid := (lo + hi) / 2
			if tails[mid] < x {        // tail too small: search the right half
				lo = mid + 1
			} else {                   // candidate position
				hi = mid
			}
		}
		if lo == len(tails) {          // x extends the longest subsequence
			tails = append(tails, x)
		} else {                       // x replaces the first tail >= x to keep tails minimal
			tails[lo] = x
		}
	}
	return len(tails) // length of tails == length of the LIS
}

