package main

// MaximalSquare returns the area of the largest all-'1' square.
func MaximalSquare(matrix [][]byte) int {
	if len(matrix) == 0 || len(matrix[0]) == 0 { // empty grid -> no square
		return 0
	}
	rows, cols := len(matrix), len(matrix[0]) // grid dimensions
	dp := make([][]int, rows+1)               // padded DP grid; dp[i][j] = side of square ending at (i-1,j-1)
	for i := range dp {                       // allocate each row (extra row/col of zeros for borders)
		dp[i] = make([]int, cols+1)
	}
	best := 0                                 // largest side length found
	for i := 1; i <= rows; i++ {              // iterate real cells using 1-based DP indices
		for j := 1; j <= cols; j++ {
			if matrix[i-1][j-1] == '1' {      // a square can only end on a '1'
				// the side is limited by the smallest of the three neighbors plus one
				dp[i][j] = min3(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
				if dp[i][j] > best {          // track the maximum side
					best = dp[i][j]
				}
			}
		}
	}
	return best * best // area = side^2
}

