package main

// CountComponents counts connected components using union-find.
func CountComponents(n int, edges [][2]int) int {
	parent := make([]int, n) // parent[i] is the representative of i's set
	for i := range parent {  // initially each node is its own root
		parent[i] = i
	}
	var find func(x int) int // find with path compression
	find = func(x int) int {
		for parent[x] != x {         // walk up to the root
			parent[x] = parent[parent[x]] // path compression by halving
			x = parent[x]
		}
		return x // representative of x's set
	}
	count := n // start with n isolated components
	for _, e := range edges { // union the endpoints of each edge
		ra, rb := find(e[0]), find(e[1]) // roots of the two endpoints
		if ra != rb {            // already connected? no change
			parent[ra] = rb     // merge the two sets
			count--             // one fewer component after a successful union
		}
	}
	return count // remaining number of components
}

