package main

// FindOrder returns a valid course order using Kahn's topological sort.
func FindOrder(numCourses int, prerequisites [][2]int) []int {
	adj := make([][]int, numCourses)    // adjacency list: prereq -> dependent courses
	indeg := make([]int, numCourses)    // number of unmet prerequisites per course
	for _, p := range prerequisites {   // p = {course, prereq}; edge prereq -> course
		course, prereq := p[0], p[1]
		adj[prereq] = append(adj[prereq], course) // prereq points to course
		indeg[course]++                           // course gains one prerequisite
	}
	queue := []int{}                  // courses with no remaining prerequisites
	for c := 0; c < numCourses; c++ { // seed the queue with in-degree-0 courses
		if indeg[c] == 0 {
			queue = append(queue, c)
		}
	}
	order := make([]int, 0, numCourses) // resulting topological order
	for len(queue) > 0 {                // process courses in dependency order
		c := queue[0]                   // take a course with no pending prerequisites
		queue = queue[1:]               // dequeue it
		order = append(order, c)        // place it next in the order
		for _, next := range adj[c] {   // relax each dependent course
			indeg[next]--               // one prerequisite satisfied
			if indeg[next] == 0 {       // all prerequisites met
				queue = append(queue, next) // it becomes ready
			}
		}
	}
	if len(order) != numCourses { // a cycle leaves some courses unprocessed
		return []int{}
	}
	return order // a valid complete ordering
}

