package main

// NumIslands counts 4-directionally connected land regions via DFS flood fill.
func NumIslands(grid [][]byte) int {
	if len(grid) == 0 || len(grid[0]) == 0 { // empty grid has no islands
		return 0
	}
	rows, cols := len(grid), len(grid[0]) // grid dimensions
	var dfs func(r, c int)                // recursive flood fill
	dfs = func(r, c int) {
		// stop at out-of-bounds cells or water/visited cells
		if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '1' {
			return
		}
		grid[r][c] = '0' // sink this land cell so it is not counted again
		dfs(r+1, c)      // explore down
		dfs(r-1, c)      // explore up
		dfs(r, c+1)      // explore right
		dfs(r, c-1)      // explore left
	}
	count := 0                        // number of islands found
	for r := 0; r < rows; r++ {       // scan every cell
		for c := 0; c < cols; c++ {
			if grid[r][c] == '1' {    // an unvisited land cell starts a new island
				count++           // count this island
				dfs(r, c)         // flood fill the whole island to mark it visited
			}
		}
	}
	return count // total islands
}

