func wordBreak(s string, wordDict []string) bool {
	words := make(map[string]bool, len(wordDict)) // set of dictionary words for O(1) lookup
	for _, w := range wordDict {                  // populate the set from the slice
		words[w] = true                           // mark each dictionary word as present
	}
	n := len(s)                                   // length of the input string
	dp := make([]bool, n+1)                       // dp[i] == true means s[:i] is segmentable
	dp[0] = true                                  // empty prefix is trivially segmentable
	for i := 1; i <= n; i++ {                     // consider every prefix length i
		for j := 0; j < i; j++ {                  // try every split point j before i
			if dp[j] && words[s[j:i]] {        // s[:j] segmentable AND s[j:i] is a word
				dp[i] = true              // then s[:i] is segmentable too
				break                     // no need to check further split points
			}
		}
	}
	return dp[n]                                  // whole string segmentable iff dp[n] is true
}

