func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
	if root == nil || root == p || root == q { // base case: empty, or we hit p or q
		return root                        // report this node up the call stack
	}
	left := lowestCommonAncestor(root.Left, p, q)   // search the left subtree
	right := lowestCommonAncestor(root.Right, p, q) // search the right subtree
	if left != nil && right != nil {           // p and q found in different subtrees
		return root                        // current node is their lowest common ancestor
	}
	if left != nil {                           // both found on the left side
		return left                        // propagate the left result upward
	}
	return right                               // otherwise propagate the right result (may be nil)
}

