package main

import "math"

type TreeNode struct {
	Val   int          // node value
	Left  *TreeNode    // left child
	Right *TreeNode    // right child
}

func isValidBST(root *TreeNode) bool {
	var check func(n *TreeNode, low, high int) bool // helper carrying allowed (low, high) range
	check = func(n *TreeNode, low, high int) bool {  // define the closure
		if n == nil {                           // empty subtree is trivially valid
			return true                     // nothing to violate
		}
		if n.Val <= low || n.Val >= high {      // value must lie strictly inside the open interval
			return false                    // out of bounds -> not a BST
		}
		return check(n.Left, low, n.Val) &&     // left subtree must stay below current value
			check(n.Right, n.Val, high)     // right subtree must stay above current value
	}
	return check(root, math.MinInt64, math.MaxInt64) // start with the widest possible bounds
}

