type TreeNode struct {
	Val   int          // node value
	Left  *TreeNode    // left child
	Right *TreeNode    // right child
}

func levelOrder(root *TreeNode) [][]int {
	res := [][]int{}                          // result: one slice per level
	if root == nil {                          // empty tree -> empty result
		return res                        // return the empty slice (not nil)
	}
	queue := []*TreeNode{root}                // BFS queue seeded with the root
	for len(queue) > 0 {                      // process until no nodes remain
		size := len(queue)                // number of nodes in the current level
		level := make([]int, 0, size)     // values collected for this level
		for i := 0; i < size; i++ {       // pop exactly this level's nodes
			node := queue[0]          // front of the queue
			queue = queue[1:]         // dequeue it
			level = append(level, node.Val) // record its value
			if node.Left != nil {     // enqueue left child if present
				queue = append(queue, node.Left)
			}
			if node.Right != nil {    // enqueue right child if present
				queue = append(queue, node.Right)
			}
		}
		res = append(res, level)          // append the finished level to the result
	}
	return res                                // levels in top-to-bottom order
}

