func kthSmallest(root *TreeNode, k int) int {
	stack := []*TreeNode{}             // explicit stack for iterative in-order traversal
	cur := root                        // current node pointer, start at the root
	for cur != nil || len(stack) > 0 { // continue while there is work left
		for cur != nil {           // descend to the leftmost unvisited node
			stack = append(stack, cur) // remember the path on the stack
			cur = cur.Left     // go left (smaller values first)
		}
		cur = stack[len(stack)-1]  // pop the next node to visit (smallest pending)
		stack = stack[:len(stack)-1]
		k--                        // we have now visited one more node in sorted order
		if k == 0 {                // this is the k-th smallest
			return cur.Val     // return its value immediately
		}
		cur = cur.Right            // then explore the right subtree
	}
	return -1                          // k larger than tree size (not expected per constraints)
}

