package main

func lengthOfLIS(nums []int) int {
	tails := []int{}                 // tails[i] = smallest tail of an increasing subseq of length i+1
	for _, x := range nums {         // process each number once
		lo, hi := 0, len(tails)  // binary-search the first tail >= x
		for lo < hi {            // standard lower-bound search
			mid := (lo + hi) / 2 // midpoint index
			if tails[mid] < x {  // tail strictly less than x -> x can extend past it
				lo = mid + 1 // search the right half
			} else {            // tail >= x -> candidate replacement position
				hi = mid     // search the left half
			}
		}
		if lo == len(tails) {    // x is larger than all tails
			tails = append(tails, x) // it extends the longest subsequence
		} else {                  // otherwise overwrite the first tail >= x
			tails[lo] = x     // keeping tails minimal for future extensions
		}
	}
	return len(tails)                // length of tails == length of the LIS
}

