package main

func maximalSquare(matrix [][]byte) int {
	if len(matrix) == 0 || len(matrix[0]) == 0 { // empty grid -> no square
		return 0                              // area is zero
	}
	rows, cols := len(matrix), len(matrix[0])     // grid dimensions
	dp := make([][]int, rows+1)                   // padded DP table (extra row/col of zeros)
	for i := range dp {                           // allocate each DP row
		dp[i] = make([]int, cols+1)           // padded width too
	}
	best := 0                                     // largest square side seen so far
	for i := 1; i <= rows; i++ {                  // iterate real rows (DP is 1-indexed)
		for j := 1; j <= cols; j++ {          // iterate real columns
			if matrix[i-1][j-1] == '1' {  // current cell is part of a possible square
				dp[i][j] = min3(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1 // limited by smallest neighbor square
				if dp[i][j] > best {  // track the maximum side length
					best = dp[i][j]
				}
			}                             // '0' cells keep dp[i][j] at its zero default
		}
	}
	return best * best                            // area is side squared
}

func min3(a, b, c int) int {
	m := a                 // assume a is smallest
	if b < m {             // b smaller?
		m = b          // update
	}
	if c < m {             // c smaller?
		m = c          // update
	}
	return m               // minimum of the three
}

