package main

import "time"

type result struct {
	url  string // which URL this result is for
	body string // fetched body, or "" on error
}

func fetchAll(fetch func(url string) (string, error), urls []string, timeout time.Duration) map[string]string {
	out := make(map[string]string, len(urls)) // aggregated results keyed by URL
	for _, u := range urls {                   // pre-seed every URL with empty result
		out[u] = ""                        // default if it errors or times out
	}
	results := make(chan result, len(urls))    // buffered so goroutines never block on send
	for _, u := range urls {                   // launch one goroutine per URL
		go func(url string) {              // capture url by value to avoid loop-variable sharing
			body, err := fetch(url)    // perform the (possibly slow) fetch
			if err != nil {            // on failure report an empty body
				results <- result{url, ""}
				return             // done with this goroutine
			}
			results <- result{url, body} // report the successful body
		}(u)
	}
	deadline := time.After(timeout)            // fires once when the overall timeout elapses
	for i := 0; i < len(urls); i++ {           // wait for up to len(urls) results
		select {
		case r := <-results:               // a goroutine finished
			out[r.url] = r.body        // record its body (overwrites the seeded "")
		case <-deadline:                   // global timeout reached first
			return out                 // return whatever has arrived; rest stay ""
		}
	}
	return out                                 // all fetches completed before the timeout
}

