package main

import "sync"

type shard struct {
	mu sync.RWMutex     // guards this shard only, so other shards stay unblocked
	m  map[string]int   // the shard's key-value storage
}

type ShardedMap struct {
	shards []*shard      // fixed set of independently-locked shards
}

func NewShardedMap(shards int) *ShardedMap {
	if shards < 1 {              // guard against zero/negative shard counts
		shards = 1           // fall back to a single shard
	}
	sm := &ShardedMap{shards: make([]*shard, shards)} // allocate the shard slice
	for i := range sm.shards {   // initialize each shard's map and mutex
		sm.shards[i] = &shard{m: make(map[string]int)}
	}
	return sm                    // ready-to-use sharded map
}

func (m *ShardedMap) shardFor(key string) *shard {
	var h uint32 = 2166136261      // FNV-1a 32-bit offset basis for a deterministic hash
	for i := 0; i < len(key); i++ { // hash each byte of the key
		h ^= uint32(key[i])    // XOR in the byte
		h *= 16777619          // multiply by the FNV prime
	}
	return m.shards[h%uint32(len(m.shards))] // map the hash onto a shard index
}

func (m *ShardedMap) Set(key string, value int) {
	s := m.shardFor(key)   // locate the owning shard
	s.mu.Lock()            // exclusive lock for the write
	s.m[key] = value       // store the value
	s.mu.Unlock()          // release promptly so others can proceed
}

func (m *ShardedMap) Get(key string) (int, bool) {
	s := m.shardFor(key)   // locate the owning shard
	s.mu.RLock()           // shared read lock allows concurrent readers
	v, ok := s.m[key]      // look up the value
	s.mu.RUnlock()         // release the read lock
	return v, ok           // value and presence flag
}

func (m *ShardedMap) Len() int {
	total := 0                     // running sum of sizes
	for _, s := range m.shards {   // visit every shard
		s.mu.RLock()           // read-lock while reading its length
		total += len(s.m)      // add this shard's entry count
		s.mu.RUnlock()         // release the read lock
	}
	return total                   // total number of keys across all shards
}

