package main

import "context"

func gen(ctx context.Context, nums []int) <-chan int {
	out := make(chan int)              // stage output channel
	go func() {                        // producer goroutine
		defer close(out)           // close when finished so consumers can range/stop
		for _, n := range nums {   // emit each input value
			select {
			case out <- n:     // send the value downstream
			case <-ctx.Done(): // context canceled/expired -> stop producing
				return
			}
		}
	}()
	return out                         // hand the channel to the next stage
}

func square(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)              // stage output channel
	go func() {                        // transformer goroutine
		defer close(out)           // close on completion
		for n := range in {        // consume upstream values
			select {
			case out <- n * n: // emit the squared value
			case <-ctx.Done(): // stop early on cancellation
				return
			}
		}
	}()
	return out                         // feed the summer stage
}

func sumPipeline(ctx context.Context, nums []int) (int, error) {
	values := square(ctx, gen(ctx, nums)) // wire generator into squarer
	total := 0                            // running partial sum
	for {
		select {
		case v, ok := <-values:        // pull the next squared value
			if !ok {              // channel closed -> pipeline finished normally
				return total, nil // full sum, no error
			}
			total += v            // accumulate
		case <-ctx.Done():            // deadline/cancellation hit
			return total, ctx.Err() // return partial sum and the context error
		}
	}
}

