package main

import (
	"runtime"
	"sync"
	"sync/atomic"
)

type SpinLock struct {
	state uint32   // 0 = unlocked, 1 = locked; accessed only via atomics
}

func (s *SpinLock) Lock() {
	for !atomic.CompareAndSwapUint32(&s.state, 0, 1) { // spin until we flip 0 -> 1
		runtime.Gosched()                          // yield so other goroutines can release the lock
	}
}

func (s *SpinLock) Unlock() {
	atomic.StoreUint32(&s.state, 0) // atomically release the lock (1 -> 0)
}

func (s *SpinLock) TryLock() bool {
	return atomic.CompareAndSwapUint32(&s.state, 0, 1) // acquire once if free, else report failure
}

func raceFreeCounter(goroutines, incrementsEach int) int {
	var lock SpinLock          // the shared spinlock guarding the counter
	counter := 0               // shared mutable state
	var wg sync.WaitGroup      // to wait for all goroutines
	wg.Add(goroutines)         // expect this many workers
	for i := 0; i < goroutines; i++ { // launch the workers
		go func() {        // each worker increments the counter
			defer wg.Done()                  // signal completion
			for j := 0; j < incrementsEach; j++ { // perform its share of increments
				lock.Lock()              // acquire exclusive access
				counter++                // critical section: safe increment
				lock.Unlock()            // release for the next goroutine
			}
		}()
	}
	wg.Wait()                  // wait until every worker finishes
	return counter             // deterministic: goroutines * incrementsEach
}

