solutionCode:
package main

import "sync"

const threshold = 1 << 11 // below this size, sort sequentially to avoid goroutine overhead

func parallelMergeSort(nums []int) []int {
	if len(nums) <= 1 {            // base case: already sorted
		return nums            // nothing to do
	}
	mid := len(nums) / 2           // split point
	var left, right []int          // sorted halves
	if len(nums) < threshold {     // small input -> avoid spawning goroutines
		left = parallelMergeSort(nums[:mid])  // sort left half sequentially
		right = parallelMergeSort(nums[mid:]) // sort right half sequentially
	} else {                       // large input -> sort halves concurrently
		var wg sync.WaitGroup  // wait for both halves
		wg.Add(2)              // two parallel tasks
		go func() {            // sort the left half in its own goroutine
			defer wg.Done()
			left = parallelMergeSort(nums[:mid])
		}()
		go func() {            // sort the right half concurrently
			defer wg.Done()
			right = parallelMergeSort(nums[mid:])
		}()
		wg.Wait()              // join before merging
	}
	return merge(left, right)      // merge the two sorted halves
}

func merge(a, b []int) []int {
	res := make([]int, 0, len(a)+len(b)) // preallocated output buffer
	i, j := 0, 0                          // cursors into a and b
	for i < len(a) && j < len(b) {        // merge while both halves have elements
		if a[i] <= b[j] {             // pick the smaller front element (stable)
			res = append(res, a[i]) // take from a
			i++
		} else {
			res = append(res, b[j]) // take from b
			j++
		}
	}
	res = append(res, a[i:]...) // drain any remaining elements of a
	res = append(res, b[j:]...) // drain any remaining elements of b
	return res                  // fully merged, sorted slice
}

