package main

import (
	"sync"
	"time"
)

// TokenBucket allows up to `capacity` bursts and refills gradually over time.
type TokenBucket struct {
	mu         sync.Mutex // guards mutable state for concurrent callers
	capacity   float64    // maximum number of tokens the bucket can hold
	tokens     float64    // current number of available tokens (fractional during refill)
	refillRate float64    // tokens added per second
	last       time.Time  // timestamp of the last refill calculation
}

// NewTokenBucket returns a bucket that starts full at `capacity`.
func NewTokenBucket(capacity int, refillPerSecond float64) *TokenBucket {
	return &TokenBucket{
		capacity:   float64(capacity),
		tokens:     float64(capacity), // start full so an initial burst is allowed
		refillRate: refillPerSecond,
		last:       time.Now(),
	}
}

// Allow consumes one token if available, returning true; otherwise false.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.last).Seconds() // seconds since we last refilled
	tb.tokens += elapsed * tb.refillRate  // add tokens accrued during that interval
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity // never exceed the bucket size
	}
	tb.last = now

	if tb.tokens >= 1 {
		tb.tokens-- // consume one token for this request
		return true
	}
	return false // not enough tokens: request is rate-limited
}

