package main

import (
	"sync"
	"time"
)

// FixedWindow permits `limit` requests per fixed `window` of wall-clock time.
type FixedWindow struct {
	mu          sync.Mutex    // protects count and windowStart
	limit       int           // max requests allowed per window
	window      time.Duration // length of each window
	count       int           // requests seen in the current window
	windowStart time.Time     // start time of the current window
}

// NewFixedWindow creates a limiter with the given per-window request limit.
func NewFixedWindow(limit int, window time.Duration) *FixedWindow {
	return &FixedWindow{
		limit:       limit,
		window:      window,
		windowStart: time.Now(),
	}
}

// Allow returns true if the current request fits within the window's limit.
func (f *FixedWindow) Allow() bool {
	f.mu.Lock()
	defer f.mu.Unlock()

	now := time.Now()
	if now.Sub(f.windowStart) >= f.window {
		// We have crossed into a new window: reset the counter and window start.
		f.windowStart = now
		f.count = 0
	}

	if f.count < f.limit {
		f.count++ // record this request
		return true
	}
	return false // limit reached for the current window
}

