package main

import "container/list"

// pair is the value stored in each list element (we keep the key to allow eviction).
type pair struct {
	key   int
	value int
}

// LRUCache evicts the least-recently-used entry once it exceeds capacity.
type LRUCache struct {
	capacity int
	items    map[int]*list.Element // key -> element holding a *pair
	order    *list.List            // front = most recently used, back = least
}

// NewLRUCache builds an empty cache with the given capacity.
func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		items:    make(map[int]*list.Element),
		order:    list.New(),
	}
}

// Get returns the value for key and marks it most-recently-used.
func (c *LRUCache) Get(key int) (int, bool) {
	el, ok := c.items[key]
	if !ok {
		return 0, false
	}
	c.order.MoveToFront(el) // touching a key refreshes its recency
	return el.Value.(*pair).value, true
}

// Put inserts or updates a key, evicting the LRU entry if capacity is exceeded.
func (c *LRUCache) Put(key, value int) {
	if el, ok := c.items[key]; ok {
		// Existing key: update value and move to front.
		el.Value.(*pair).value = value
		c.order.MoveToFront(el)
		return
	}

	// New key: push to the front as most-recently-used.
	el := c.order.PushFront(&pair{key: key, value: value})
	c.items[key] = el

	if c.order.Len() > c.capacity {
		// Evict the least-recently-used node at the back.
		oldest := c.order.Back()
		if oldest != nil {
			c.order.Remove(oldest)
			delete(c.items, oldest.Value.(*pair).key)
		}
	}
}

