package main

import "sync"

// Cache implements the cache-aside pattern: on a miss, it loads and stores.
type Cache struct {
	mu    sync.Mutex        // serializes loads to prevent duplicate work
	items map[string]string // the in-memory store
}

// NewCache returns an empty cache.
func NewCache() *Cache {
	return &Cache{items: make(map[string]string)}
}

// GetOrLoad returns the cached value for key, or loads it via loader on a miss.
func (c *Cache) GetOrLoad(key string, loader func() (string, error)) (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	// Under the lock, re-check the map so concurrent callers load only once.
	if v, ok := c.items[key]; ok {
		return v, nil
	}

	v, err := loader()
	if err != nil {
		return "", err // do not cache failures
	}
	c.items[key] = v // populate the cache for subsequent readers
	return v, nil
}

