package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
)

// Sign returns the hex-encoded HMAC-SHA256 of payload under secret.
func Sign(payload, secret string) string {
	mac := hmac.New(sha256.New, []byte(secret)) // keyed hash using the secret
	mac.Write([]byte(payload))                  // feed the message bytes
	sum := mac.Sum(nil)                         // finalize the MAC
	return hex.EncodeToString(sum)              // encode to a readable hex string
}

// Verify recomputes the signature and compares it in constant time.
func Verify(payload, secret, signature string) bool {
	expected := Sign(payload, secret)
	// hmac.Equal is constant-time, preventing timing side-channels on comparison.
	return hmac.Equal([]byte(expected), []byte(signature))
}

