package main

// Handler processes a message and returns a result (a tiny stand-in for http.Handler).
type Handler func(msg string) string

// Middleware wraps a Handler to add behavior around it.
type Middleware func(Handler) Handler

// Chain composes middleware around h so that mws[0] is the outermost layer.
func Chain(h Handler, mws ...Middleware) Handler {
	// Apply middleware in reverse: the last one wraps h first, so the first
	// listed middleware ends up on the outside and runs first on the way in.
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

