package main

import "sync"

// Hub is a simple fan-out publish/subscribe broker backed by channels.
type Hub struct {
	mu   sync.Mutex    // guards the subscribers slice
	subs []chan string // one channel per subscriber
}

// NewHub returns an empty hub ready for subscribers.
func NewHub() *Hub {
	return &Hub{}
}

// Subscribe registers and returns a new receive-only channel.
func (h *Hub) Subscribe() <-chan string {
	h.mu.Lock()
	defer h.mu.Unlock()

	ch := make(chan string, 16) // small buffer so a slow reader doesn't stall publishers
	h.subs = append(h.subs, ch)
	return ch
}

// Publish delivers msg to every subscriber, dropping it for any full buffer.
func (h *Hub) Publish(msg string) {
	h.mu.Lock()
	defer h.mu.Unlock()

	for _, ch := range h.subs {
		select {
		case ch <- msg: // deliver if the subscriber has room
		default: // non-blocking: drop the message for a slow subscriber
		}
	}
}

