package main

import "strconv"

// Page returns up to limit items after the cursor, plus the next cursor.
// items must be sorted ascending. An empty cursor starts from the beginning.
func Page(items []int, cursor string, limit int) ([]int, string) {
	after := -1 << 62 // sentinel meaning "before everything" for an empty cursor
	if cursor != "" {
		if v, err := strconv.Atoi(cursor); err == nil {
			after = v // resume strictly after this value
		}
	}

	result := make([]int, 0, limit)
	for _, it := range items {
		if it <= after {
			continue // skip everything up to and including the cursor
		}
		result = append(result, it)
		if len(result) == limit {
			break // page is full
		}
	}

	if len(result) == 0 {
		return result, "" // no more items: empty next cursor
	}
	next := strconv.Itoa(result[len(result)-1]) // cursor points at the last item returned
	return result, next
}

