solutionCode:
package main

import "time"

// Retry calls fn up to maxAttempts times, backing off exponentially between tries.
// The sleep function is injected so tests can pass a no-op for determinism.
func Retry(fn func() error, maxAttempts int, base time.Duration, sleep func(time.Duration)) error {
	var err error
	delay := base
	for attempt := 0; attempt < maxAttempts; attempt++ {
		err = fn()
		if err == nil {
			return nil // success: stop retrying
		}
		if attempt < maxAttempts-1 {
			sleep(delay) // wait before the next attempt
			delay *= 2   // exponential backoff: double the delay each round
		}
	}
	return err // all attempts exhausted; surface the last error
}

