package main

import "sync"

// IdempotencyStore ensures an operation keyed by a client-supplied key runs at most once.
type IdempotencyStore struct {
	mu      sync.Mutex        // serializes access to results
	results map[string]string // key -> the result produced the first time
}

// NewIdempotencyStore returns an empty store.
func NewIdempotencyStore() *IdempotencyStore {
	return &IdempotencyStore{results: make(map[string]string)}
}

// Do runs op for a key exactly once, returning the cached result on repeats.
func (s *IdempotencyStore) Do(key string, op func() (string, error)) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if v, ok := s.results[key]; ok {
		return v, nil // already processed this key: return the original result
	}

	v, err := op()
	if err != nil {
		return "", err // do not store failures so a retry can succeed
	}
	s.results[key] = v // remember the result for future duplicate requests
	return v, nil
}

