solutionCode:
package main

import "sync"

// ProcessJobs runs work over jobs using at most `workers` goroutines,
// returning results in the same order as the input jobs.
func ProcessJobs(jobs []int, workers int, work func(int) int) []int {
	results := make([]int, len(jobs)) // pre-sized so each index is written by one worker
	if len(jobs) == 0 {
		return results
	}
	if workers < 1 {
		workers = 1 // guard against a non-positive worker count
	}

	indexes := make(chan int) // stream of job indices to process
	var wg sync.WaitGroup

	// Start a fixed pool of workers (fan-out).
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range indexes {
				results[i] = work(jobs[i]) // each i is unique, so no race on results
			}
		}()
	}

	// Feed all job indices, then close so workers can drain and exit.
	for i := range jobs {
		indexes <- i
	}
	close(indexes)

	wg.Wait() // fan-in: wait for every worker to finish
	return results
}

