package main

import (
	"context"
	"sync"
	"sync/atomic"
)

// RunWorkers launches `workers` goroutines that call step in a loop until ctx
// is cancelled, then waits for a clean shutdown and returns total steps done.
func RunWorkers(ctx context.Context, workers int, step func(id int)) int {
	var count int64 // total steps performed across all workers (atomic)
	var wg sync.WaitGroup

	for id := 0; id < workers; id++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return // context cancelled: exit the goroutine cleanly
				default:
					step(id)                    // do one unit of work
					atomic.AddInt64(&count, 1)  // race-free increment of the counter
				}
			}
		}(id)
	}

	wg.Wait() // block until every worker has observed cancellation and returned
	return int(atomic.LoadInt64(&count))
}
